// Benchmark entry point
// Generated by CMake

#include "benchmarks.hpp"
#include "core/Logger/Logger.hpp"
#include <iostream>
#include <thread>
#include <mutex>
#include <condition_variable>

void benchmark_core() {
    NLM_BENCHMARK(benchmark_core_creation)
    {
        nlm::core::Logger logger("benchmark");
        logger.info("Core benchmark started");
    }
    
    NLM_BENCHMARK(benchmark_memory_allocation)
    {
        std::vector<double> data(1000000, 1.0);
        double sum = std::accumulate(data.begin(), data.end(), 0.0);
        (void)sum;
    }
    
    NLM_BENCHMARK(benchmark_thread_synchronization)
    {
        std::mutex mtx;
        std::condition_variable cv;
        bool ready = false;
        
        auto worker = [&]() {
            std::unique_lock<std::mutex> lock(mtx);
            ready = true;
            cv.notify_one();
        };
        
        std::thread t(worker);
        
        std::unique_lock<std::mutex> lock(mtx);
        cv.wait(lock, [&]() { return ready; });
        t.join();
    }
    
    NLM_BENCHMARK(benchmark_math_operations)
    {
        double result = 0.0;
        for (int i = 0; i < 1000000; ++i) {
            result += std::sin(static_cast<double>(i)) * std::cos(static_cast<double>(i));
        }
        (void)result;
    }
}

void benchmark_brain() {
    NLM_BENCHMARK(benchmark_neuron_creation)
    {
        // Neuron creation benchmark
        std::vector<double> weights(1000, 0.0);
        double bias = 0.0;
        
        for (int i = 0; i < 10000; ++i) {
            double activation = 0.0;
            for (size_t j = 0; j < weights.size(); ++j) {
                activation += weights[j] * 1.0; // Input = 1.0
            }
            activation += bias;
            // Apply activation function
            activation = 1.0 / (1.0 + std::exp(-activation));
        }
    }
    
    NLM_BENCHMARK(benchmark_synapse_operations)
    {
        // Synapse operations benchmark
        std::vector<std::vector<double>> weights(1000, std::vector<double>(1000, 0.0));
        
        for (int epoch = 0; epoch < 100; ++epoch) {
            for (int i = 0; i < 1000; ++i) {
                for (int j = 0; j < 1000; ++j) {
                    weights[i][j] += 0.01; // Small update
                }
            }
        }
    }
}

void benchmark_memory() {
    NLM_BENCHMARK(benchmark_working_memory)
    {
        // Working memory benchmark
        std::vector<std::vector<double>> memory(100, std::vector<double>(1000, 0.0));
        
        for (int t = 0; t < 1000; ++t) {
            for (int i = 0; i < 100; ++i) {
                // Competitive dynamics
                double max_activity = 0.0;
                int winner = 0;
                
                for (int j = 0; j < 1000; ++j) {
                    if (memory[i][j] > max_activity) {
                        max_activity = memory[i][j];
                        winner = j;
                    }
                }
                
                // Update winner
                memory[i][winner] += 0.1;
                
                // Decay other activities
                for (int j = 0; j < 1000; ++j) {
                    if (j != winner) {
                        memory[i][j] *= 0.95;
                    }
                }
            }
        }
    }
}

void print_results() {
    auto& suite = nlm::benchmarks::get_benchmark_suite();
    
    std::cout << std::setw(40) << std::left << "Benchmark";
    std::cout << std::setw(15) << std::left << "Duration (ms)";
    std::cout << std::setw(15) << std::left << "Memory (MB)";
    std::cout << std::setw(15) << std::left << "Operations";
    std::cout << std::setw(15) << std::left << "Ops/sec";
    std::cout << "\n";
    
    for (const auto& result : suite.get_results()) {
        std::cout << std::setw(40) << std::left << result.name;
        std::cout << std::setw(15) << std::left << std::fixed << std::setprecision(3) << result.duration_ms;
        std::cout << std::setw(15) << std::left << std::fixed << std::setprecision(2) << result.memory_usage_mb;
        std::cout << std::setw(15) << std::left << result.operations_performed;
        std::cout << std::setw(15) << std::left << std::fixed << std::setprecision(0) << result.operations_per_second;
        std::cout << "\n";
    }
}

int main() {
    std::cout << "NLM Benchmark Suite\n";
    std::cout << "===================\n\n";
    
    benchmark_core();
    benchmark_brain();
    benchmark_memory();
    
    print_results();
    
    // Save results to file
    auto& suite = nlm::benchmarks::get_benchmark_suite();
    suite.save_to_file("benchmark_results.json");
    
    std::cout << "\nBenchmark results saved to benchmark_results.json\n";
    
    return 0;
}
